files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', monospace;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}
.card {
  background: var(--card);
  border: 4px solid var(--accent);
  padding: 24px;
  width: 100%;
  max-width: 400px;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
}
h1 {
  font-size: 1.5rem;
  margin: 0 0 16px;
  letter-spacing: 2px;
  text-transform: uppercase;
}
.question {
  font-size: 2rem;
  margin: 0 0 24px;
  font-weight: bold;
}
.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
}
button {
  font-family: inherit;
  font-size: 1.25rem;
  cursor: pointer;
  border: 3px solid var(--text);
  background: var(--bg);
  color: var(--text);
  padding: 12px 24px;
  transition: background 0.1s, transform 0.1s;
}
button:hover { background: var(--accent); color: #fff; }
button:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
button:active { transform: translate(2px, 2px); }
button:disabled { opacity: 0.5; cursor: not-allowed; }
.answer { min-width: 80px; }
.score-line { font-size: 1.25rem; margin: 0 0 16px; }
.controls { display: flex; gap: 16px; justify-content: center; }
.control { font-size: 1rem; padding: 8px 16px; }
@media (max-width: 400px) {
  .card { padding: 16px; }
  .question { font-size: 1.5rem; }
  button { font-size: 1rem; padding: 10px 16px; }
}

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

let current = 0;
let score = 0;
let answered = false;

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

function render() {
  if (current >= questions.length) {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
    return;
  }
  const q = questions[current];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = false;
  answerB.disabled = false;
  nextBtn.disabled = !answered;
  answered = false;
}

function handleAnswer(choice) {
  if (answered || current >= questions.length) return;
  answered = true;
  answerA.disabled = true;
  answerB.disabled = true;
  if (choice === questions[current].correct) {
    score += 1;
    scoreEl.textContent = score;
  }
  nextBtn.disabled = false;
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (!answered) return;
  current += 1;
  render();
});

restartBtn.addEventListener('click', () => {
  current = 0;
  score = 0;
  answered = false;
  scoreEl.textContent = '0';
  render();
});

render();
